def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find contiguous same-color runs on each border; each is a ray source.
    bands = []
    for side, vals in (('top', grid[0]), ('bottom', grid[-1]),
                       ('left', [grid[r][0] for r in range(h)]),
                       ('right', [grid[r][-1] for r in range(h)])):
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color, start = vals[i], i
            while i < len(vals) and vals[i] == color:
                i += 1
            if i - start >= 2:
                bands.append((side, start, i - 1, color))

    band_colors = {color for _, _, _, color in bands}
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] not in band_colors]
    if not marks:
        return out
    ray_color = Counter(v for _, _, v in marks).most_common(1)[0][0]
    targets = {(r, c) for r, c, v in marks if v == ray_color}

    for side, start, end, _ in bands:
        length = end - start + 1
        axis = (lambda r, c: c) if side in ('top', 'bottom') else (lambda r, c: r)
        target_lanes = {axis(r, c) for r, c in targets if start <= axis(r, c) <= end}
        if length == 3:
            lanes = {start + 1, end}
        else:
            # Bands cast alternate lanes; aligned isolated marks are included.
            lanes = {p for p in range(start, end + 1) if p % 2 == start % 2}
            lanes.update(target_lanes)
            if length % 2 == 0 and end not in lanes:
                lanes.add(end)
            # Long empty bands fill their inward span.
            if length >= 9 and not target_lanes:
                lanes = set(range(start, end + 1))
        for p in lanes:
            if side == 'top': r, c, dr, dc = 1, p, 1, 0
            elif side == 'bottom': r, c, dr, dc = h - 2, p, -1, 0
            elif side == 'left': r, c, dr, dc = p, 1, 0, 1
            else: r, c, dr, dc = p, w - 2, 0, -1
            while 0 <= r < h and 0 <= c < w:
                if (r, c) in targets:
                    out[r][c] = 4
                    break
                if grid[r][c] in band_colors:
                    break
                out[r][c] = ray_color
                r += dr
                c += dc
    return out
